mapper.sql:
where p.publishstatus = '已发布' and l.title is not null and trim(l.title) != ''
and p.category = #{category}
and (l.title like concat('%', #{keyword}, '%') or l.summary like concat('%', #{keyword}, '%'))

mapper.select:
select ,
       l.title as title, l.summary as summary, l.keywords as keywords
  from u_s_post p
  inner join u_s_post_lang l
    on l.postcode = p.postcode and l.lang = #{lang}


 limit #{offset}, #{limit}

select , l.title as title, l.summary as summary from u_s_post p left join u_s_post_lang l on l.postcode = p.postcode and l.lang = #{lang}
and p.publishstatus = #{publishStatus}
and p.category = #{category}
and (l.title like concat('%', #{keyword}, '%') or p.slug like concat('%', #{keyword}, '%') or p.postcode like concat('%', #{keyword}, '%'))
order by p.sortnum, p.publishtime desc, p.createtime desc

select 
  from u_s_post p
 where p.postcode = #{postCode}

select count(*)
  from u_s_post
 where slug = #{slug}

  and postcode != #{exceptPostCode}

